import"./chunk-2NFLSA4Y.js";var i={buoyancy:{theory:{concept:"[[Archimedes' principle: a body immersed in a liquid is pushed upwards by a buoyant force equal to the weight of the liquid it displaces, F_A = \u03C1_l \xB7 g \xB7 V_sub.]] The buoyant force appears because the pressure in a liquid grows with depth, so the liquid pushes harder on the bottom of the body than on its top."},section:{compare:{title:"Float, hover or sink",text:"Compare the densities. If the body is less dense than the liquid (cork, wood, ice in water), the buoyant force on the fully submerged body is bigger than its weight, so it rises and floats. If it is denser (iron, stone), it sinks. If the densities are equal, it hovers wherever it is put, like a fish or a submarine."},floating:{title:"How deep a floating body sits",text:"[[A floating body sinks just far enough to displace its own weight of liquid.]] So the share under the surface equals \u03C1_body / \u03C1_liquid: wood of 600 kg/m\xB3 floats 60 % under water, ice about 90 % \u2014 the famous tip of the iceberg. Gravity cancels out: on the Moon a boat would float exactly as deep as on the Earth."},scale:{title:"Weighing under water",text:"Hang a body on a spring scale and lower it into water: the reading falls as more of it goes under, because the buoyant force carries part of the weight. Once it is completely under water the reading stops changing \u2014 the buoyant force no longer depends on depth. The loss of weight is exactly the weight of the displaced water."},ships:{title:"Why steel ships float",text:"Steel is almost eight times denser than water, but a ship is mostly air inside a thin steel shell. Its average density is lower than water's, and its hull displaces a great volume of water. A submarine floods or empties its tanks to change its average density; a fish does the same with its swim bladder. A hot-air balloon floats in air for the same reason."},examples:{title:"Different liquids",text:"The Dead Sea is so salty (about 1 240 kg/m\xB3) that people float in it without effort, and an egg that sinks in tap water floats there. Oil floats on water because it is less dense. Mercury is so dense (13 534 kg/m\xB3) that iron floats on it \u2014 only gold and a few other metals sink."},check:{title:"Check your understanding",text:"How much of a block of wood (500 kg/m\xB3) is under water? (Half.) Does iron float on mercury? (Yes.) Why does the scale reading stop changing once a stone is completely under water? Would a boat float deeper on the Moon? (No.) Try each answer in the simulation."}},formula:{archimedes:"Buoyant force: the weight of the displaced liquid",compare:"Less dense than the liquid: floats \xB7 equal: hovers \xB7 denser: sinks",fraction:"Share of a floating body under the surface",apparent:"Weight in the liquid (what a spring scale shows)",motion:"Motion of the body: buoyancy, weight and water resistance"},variable:{liquid:"Density of the liquid",body:"Density of the body",volume:"Volume under the surface, m\xB3"},assumption:{still:"The liquid is at rest, incompressible and equally dense everywhere.",upright:"The cube stays upright and does not tip over.",resistance:"Water resistance and waves are simplified; the water dragged along with the body is ignored.",tank:"The tank is 1.6 m \xD7 0.8 m with 1 m of liquid, and nothing overflows."},param:{experiment:"Experiment",density:"Density of the body",liquid:"Liquid",start:"Release",size:"Size of the cube",gravity:"Gravity",timeStep:"Simulation timestep"},hint:{density:"Mass per cubic metre. Water is 1 000 kg/m\xB3."},preset:{free:"Floating and sinking",scale:"On a spring scale",cork:"Cork",wood:"Wood",ice:"Ice",egg:"Egg",aluminium:"Aluminium",iron:"Iron",gold:"Gold",water:"Fresh water",seaWater:"Sea water",deadSea:"Dead Sea",oil:"Oil",alcohol:"Alcohol",mercury:"Mercury",drop:"Drop from above",surface:"At the surface",underwater:"Under the surface"},measure:{submerged:"Share under the surface",expected:"Expected share when floating",scaleReading:"Spring scale reading",weight:"Weight",buoyancy:"Buoyant force",displacedMass:"Mass of displaced liquid",bodyMass:"Mass of the body",netForce:"Net upward force",levelRise:"Rise of the liquid level",velocity:"Velocity (up +)"},view:{floats:"Floats: \u03C1 = {body} < {liquid} \xB7 {submerged} under the surface (expected {expected})",sinks:"Sinks: \u03C1 = {body} > {liquid} \xB7 {submerged} under the surface",hovers:"Hovers: \u03C1 = {body} = {liquid}",levelOption:"Liquid level"},graph:{submerged:"Share under the surface against time",scale:"Scale reading against depth"},challenge:{iceberg:{title:"The tip of the iceberg",description:"Float ice in sea water. How much of it stays above the surface?",hint:"Choose ice and sea water."},ironFloats:{title:"Floating iron",description:"Make a body denser than 7 000 kg/m\xB3 float.",hint:"It needs a liquid denser than iron."},deadSea:{title:"The Dead Sea",description:"Float something that would sink in fresh water.",hint:"Try an egg in the Dead Sea."},hover:{title:"Like a submarine",description:"Release a body under the surface so that it stays where it is.",hint:"Make its density exactly equal to the liquid's."},weigh:{title:"Weighing under water",description:"Lower a body that sinks completely under the surface on the spring scale. How much lighter does it seem?",hint:"The loss equals the weight of the displaced liquid: \u03C1_l \xB7 g \xB7 V."},moon:{title:"A boat on the Moon",description:"With the Moon's gravity, show that a floating body sits just as deep as on the Earth.",hint:"V_sub / V = \u03C1_b / \u03C1_l \u2014 g does not appear."}}}},a={sim:i};export{a as default,i as sim};
